// Helper functions
func getFormTitle(isEdit bool) string {
	if isEdit {
		return "Edit User"
	}
	return "Create New User"
}

func getSubmitButtonText(isEdit bool) string {
	if isEdit {
		return "Update User"
	}
	return "Create User"
}

func getFieldValue(user *User, field string) string {
	if user == nil {
		return ""
	}
	switch field {
	case "name":
		return user.Name
	case "email":
		return user.Email
	case "phone":
		return user.Phone
	case "department":
		return user.Department
	case "role":
		return user.Role
	case "status":
		return user.Status
	default:
		return ""
	}
}

func getFieldError(errors map[string]string, field string) string {
	if errors == nil {
		return ""
	}
	return errors[field]
}

